'use client';

import { useState } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { useRouter } from 'next/navigation';
import { api } from '@/lib/api';
import type { Client } from '@crm/types';
import { Badge } from '@/components/ui/Badge';
import { Button } from '@/components/ui/Button';
import { Modal } from '@/components/ui/Modal';

const statusV = { active:'green', pending:'orange', inactive:'gray' } as const;
const statusL = { active:'Активный', pending:'На рассмотрении', inactive:'Неактивный' } as const;
const riskV   = { low:'green', medium:'orange', high:'red' } as const;
const riskL   = { low:'Низкий', medium:'Средний', high:'Высокий' } as const;
const segV    = { Premium:'purple', Standard:'gray' } as const;
const clientColor = { large:'#1d4ed8', sme:'#7c3aed', holding:'#0f766e', international:'#d97706' } as const;

export default function ClientsPage() {
  const router = useRouter();
  const qc     = useQueryClient();
  const [open, setOpen] = useState(false);
  const [form, setForm] = useState({ name:'', type:'Крупный бизнес', industry:'', inn:'', city:'Ташкент', phone:'', email:'', manager:'', segment:'Standard' });

  const { data: clients = [], isLoading } = useQuery<Client[]>({
    queryKey: ['clients'],
    queryFn:  () => api.get('/clients'),
  });

  const create = useMutation({
    mutationFn: (body: typeof form) => api.post('/clients', body),
    onSuccess: () => { qc.invalidateQueries({ queryKey: ['clients'] }); setOpen(false); setForm({ name:'', type:'Крупный бизнес', industry:'', inn:'', city:'Ташкент', phone:'', email:'', manager:'', segment:'Standard' }); },
  });

  if (isLoading) return <div className="flex items-center justify-center h-64 text-gray-400 text-sm">Загрузка...</div>;

  return (
    <div>
      <div className="flex items-center justify-between mb-5">
        <div>
          <h2 className="text-2xl font-extrabold tracking-tight">Клиенты</h2>
          <p className="text-sm text-gray-400 mt-0.5">{clients.length} компаний в базе</p>
        </div>
        <Button onClick={() => setOpen(true)}>+ Новый клиент</Button>
      </div>

      <div className="bg-white border border-gray-200 rounded-xl overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full">
            <thead>
              <tr className="bg-gray-50 border-b border-gray-200">
                {['Компания','Тип','Отрасль','Менеджер','Сегмент','Статус','Риск','Последний контакт'].map(h => (
                  <th key={h} className="text-left px-4 py-2.5 text-[11px] font-semibold uppercase tracking-wider text-gray-400">{h}</th>
                ))}
              </tr>
            </thead>
            <tbody>
              {clients.map(c => (
                <tr key={c.id} onClick={() => router.push(`/clients/${c.id}`)}
                  className="border-b border-gray-100 last:border-0 cursor-pointer hover:bg-gray-50 transition-colors">
                  <td className="px-4 py-3">
                    <div className="flex items-center gap-2.5">
                      <div className="w-8 h-8 rounded-lg flex items-center justify-center text-white text-[11px] font-bold flex-shrink-0"
                        style={{ background: clientColor[c.type_en] ?? '#1d4ed8' }}>
                        {c.short_name || c.name[0]}
                      </div>
                      <div>
                        <div className="text-sm font-semibold">{c.name}</div>
                        <div className="text-xs text-gray-400">{c.city}</div>
                      </div>
                    </div>
                  </td>
                  <td className="px-4 py-3"><Badge variant="blue">{c.type}</Badge></td>
                  <td className="px-4 py-3 text-sm text-gray-500">{c.industry || '—'}</td>
                  <td className="px-4 py-3 text-sm">{c.manager || '—'}</td>
                  <td className="px-4 py-3"><Badge variant={segV[c.segment] ?? 'gray'}>{c.segment}</Badge></td>
                  <td className="px-4 py-3"><Badge variant={statusV[c.status]}>{statusL[c.status]}</Badge></td>
                  <td className="px-4 py-3"><Badge variant={riskV[c.risk_level]}>{riskL[c.risk_level]}</Badge></td>
                  <td className="px-4 py-3 text-xs text-gray-400">{c.last_contact || '—'}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      <Modal open={open} title="Новый клиент" onClose={() => setOpen(false)}
        footer={<>
          <Button variant="ghost" onClick={() => setOpen(false)}>Отмена</Button>
          <Button onClick={() => create.mutate(form)} disabled={!form.name || create.isPending}>
            {create.isPending ? 'Создание...' : 'Создать клиента'}
          </Button>
        </>}>
        <div className="space-y-3">
          <Field label="Название *"><input value={form.name} onChange={e=>setForm({...form,name:e.target.value})} className="form-input" placeholder="ООО Пример"/></Field>
          <div className="grid grid-cols-2 gap-3">
            <Field label="Тип">
              <select value={form.type} onChange={e=>setForm({...form,type:e.target.value})} className="form-input">
                {['Крупный бизнес','МСП','Холдинг','Международные'].map(t=><option key={t}>{t}</option>)}
              </select>
            </Field>
            <Field label="Отрасль"><input value={form.industry} onChange={e=>setForm({...form,industry:e.target.value})} className="form-input" placeholder="Банки, IT..."/></Field>
          </div>
          <div className="grid grid-cols-2 gap-3">
            <Field label="ИНН"><input value={form.inn} onChange={e=>setForm({...form,inn:e.target.value})} className="form-input" placeholder="1234567890"/></Field>
            <Field label="Город"><input value={form.city} onChange={e=>setForm({...form,city:e.target.value})} className="form-input"/></Field>
          </div>
          <div className="grid grid-cols-2 gap-3">
            <Field label="Телефон"><input value={form.phone} onChange={e=>setForm({...form,phone:e.target.value})} className="form-input"/></Field>
            <Field label="Email"><input value={form.email} onChange={e=>setForm({...form,email:e.target.value})} className="form-input"/></Field>
          </div>
          <div className="grid grid-cols-2 gap-3">
            <Field label="Менеджер"><input value={form.manager} onChange={e=>setForm({...form,manager:e.target.value})} className="form-input"/></Field>
            <Field label="Сегмент">
              <select value={form.segment} onChange={e=>setForm({...form,segment:e.target.value})} className="form-input">
                <option>Standard</option><option>Premium</option>
              </select>
            </Field>
          </div>
        </div>
      </Modal>
    </div>
  );
}

function Field({ label, children }: { label: string; children: React.ReactNode }) {
  return (
    <div>
      <label className="block text-[11px] font-semibold uppercase tracking-wider text-gray-400 mb-1">{label}</label>
      {children}
    </div>
  );
}
